#!/usr/bin/env python3
import sqlite3, json
from pathlib import Path
db_path = Path('tmpPlan/agent-test/d08/laew_demo.db')
try:
    if db_path.exists(): db_path.unlink()
    conn = sqlite3.connect(str(db_path))
    conn.executescript('CREATE TABLE providers(id INTEGER PRIMARY KEY, name TEXT NOT NULL, protocol TEXT DEFAULT \'openai\', is_active INTEGER DEFAULT 0); INSERT INTO providers VALUES(1,\'demo\',\'openai\',1); INSERT INTO providers VALUES(2,\'mock\',\'anthropic\',0); CREATE TABLE sessions(id INTEGER PRIMARY KEY, provider_id INTEGER REFERENCES providers(id), created_at TEXT DEFAULT (datetime(\'now\'))); INSERT INTO sessions VALUES(1,1,\'2026-09-11\');')
    conn.commit()
    ro = sqlite3.connect(f'file:{db_path}?mode=ro', uri=True)
    tables = ro.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name").fetchall()
    result = {'tables': {}, 'db_path': str(db_path), 'mode': 'ro'}
    for (t,) in tables:
        schema = ro.execute(f"SELECT sql FROM sqlite_master WHERE name=\'{t}\''").fetchone()
        count = ro.execute(f'SELECT COUNT(*) FROM "{t}"').fetchone()[0]
        result['tables'][t] = {'schema': schema[0] if schema else None, 'row_count': count}
    ro.close()
    print(json.dumps(result, indent=2, ensure_ascii=False))
    db_path.unlink()
except Exception as e:
    print(json.dumps({'error': str(e)}))

#!/usr/bin/env python3
import subprocess, plistlib
from pathlib import Path
def run_profiler(dt):
    try:
        r = subprocess.run(['system_profiler', '-xml', dt], capture_output=True, text=True, timeout=30)
        if r.returncode == 0 and r.stdout.strip():
            return plistlib.loads(r.stdout.encode())
    except Exception:
        pass
    return None
md = ['# macOS 系统审计报告\n']
hw = run_profiler('SPHardwareDataType')
md.append('## 硬件\n')
if hw and isinstance(hw, list) and hw:
    items = hw[0].get('_items', [{}])[0]
    for k in ['machine_name', 'cpu_type', 'physical_memory', 'model_identifier', 'chip_type']:
        if k in items:
            md.append(f'- **{k}**: {items[k]}')
md.append('')
sw = run_profiler('SPSoftwareDataType')
md.append('## 软件\n')
if sw and isinstance(sw, list) and sw:
    items = sw[0].get('_items', [{}])[0]
    for k in ['os_version', 'kernel_version', 'boot_volume', 'computer_name']:
        if k in items:
            md.append(f'- **{k}**: {items[k]}')
md.append('')
md.append('## 安全\n')
for check, cmd in [('SIP', ['csrutil', 'status']), ('Gatekeeper', ['spctl', '--status'])]:
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=5)
        md.append(f'- **{check}**: {r.stdout.strip().splitlines()[0] if r.stdout.strip() else "unknown"}')
    except Exception:
        md.append(f'- **{check}**: unavailable')
md.append('')
apps = run_profiler('SPApplicationsDataType')
md.append('## 应用\n')
count = 0
if apps and isinstance(apps, list) and apps:
    for item in apps[0].get('_items', [])[:10]:
        name = item.get('_name', 'unknown')
        ver = item.get('version', 'N/A')
        md.append(f'- {name} ({ver})')
        count += 1
if count == 0:
    md.append('- (无法获取应用列表)')
md.append('')
out = Path('tmpPlan/agent-test/dr10/dr10_report.md')
out.write_text('\n'.join(md), encoding='utf-8')
print(f'报告已生成: {out}')
print(f'二级标题数: {sum(1 for l in md if l.startswith("## "))}')
